mapper.select:
SELECT EXISTS (
SELECT 1
FROM settlement_invitation
WHERE settlement_id = #{settlementId}
AND user_id = #{userId}
AND invitation_status = 'INVITED'
)

mapper.update:
UPDATE settlement_invitation
SET invitation_status = 'ACCEPTED',
accepted_at = #{acceptedAt}
WHERE invitation_id = #{invitationId}
AND invitation_status = 'INVITED'
